INSERT INTO appointment_db.translations (translation_id, phrase, language_code, translated_phrase, created_at, updated_at) VALUES (132, 'you_are', 'zh', '您是一个友好的电话助手，为', '2025-07-23 18:55:50', '2025-07-23 18:55:50');
INSERT INTO appointment_db.translations (translation_id, phrase, language_code, translated_phrase, created_at, updated_at) VALUES (133, 'intro', 'en', 'Greet callers warmly. Answer questions clearly and briefly. Offer the service name, price, and duration only when asked. Help with bookings by asking what service and time they prefer.
INSERT INTO appointment_db.translations (translation_id, phrase, language_code, translated_phrase, created_at, updated_at) VALUES (134, 'intro', 'ar', 'رحب بالمتصلين بحرارة. أجب على الأسئلة بوضوح وإيجاز. قدم اسم الخدمة والسعر والمدة فقط عند الطلب. ساعد في الحجوزات بالسؤال عن الخدمة والوقت المفضلين.
INSERT INTO appointment_db.translations (translation_id, phrase, language_code, translated_phrase, created_at, updated_at) VALUES (135, 'intro', 'fr', 'Accueillez les appelants chaleureusement. Répondez aux questions clairement et brièvement. Proposez le nom du service, le prix et la durée uniquement lorsqu\'on vous le demande. Aidez aux réservations en demandant quel service et à quelle heure ils préfèrent.
INSERT INTO appointment_db.translations (translation_id, phrase, language_code, translated_phrase, created_at, updated_at) VALUES (136, 'intro', 'zh', '热情地问候来电者。 清晰简洁地回答问题。 仅在被问到时提供服​​务名称、价格和持续时间。 通过询问他们喜欢什么服务和时间来帮助预订。
INSERT INTO appointment_db.translations (translation_id, phrase, language_code, translated_phrase, created_at, updated_at) VALUES (137, 'current_date_and_time', 'en', 'Use this information to provide time-aware responses, such as suggesting availability later today or referencing specific days (e.g., \'tomorrow\', \'Friday afternoon\').
INSERT INTO appointment_db.translations (translation_id, phrase, language_code, translated_phrase, created_at, updated_at) VALUES (138, 'current_date_and_time', 'ar', 'استخدم هذه المعلومات لتقديم ردود واعية بالوقت، مثل اقتراح أوقات متاحة لاحقًا اليوم أو الإشارة إلى أيام محددة (مثل \'غدًا\'، \'بعد ظهر الجمعة\').
INSERT INTO appointment_db.translations (translation_id, phrase, language_code, translated_phrase, created_at, updated_at) VALUES (139, 'current_date_and_time', 'fr', 'Utilisez ces informations pour fournir des réponses tenant compte du temps, comme suggérer des disponibilités plus tard dans la journée ou faire référence à des jours spécifiques (par exemple, \'demain\', \'vendredi après-midi\').
INSERT INTO appointment_db.translations (translation_id, phrase, language_code, translated_phrase, created_at, updated_at) VALUES (140, 'current_date_and_time', 'zh', '使用此信息提供时间感知的响应，例如建议今天晚些时候的空闲时间或参考特定日期（例如“明天”、“周五下午”）。
