INSERT INTO appointment_db.translations (translation_id, phrase, language_code, translated_phrase, created_at, updated_at) VALUES (165, 'functions_calling_instructions', 'en', 'Always confirm with the customer before performing any appointment-related action (booking, rescheduling, or canceling).
INSERT INTO appointment_db.translations (translation_id, phrase, language_code, translated_phrase, created_at, updated_at) VALUES (166, 'functions_calling_instructions', 'ar', 'يجب التأكيد مع العميل دائمًا قبل تنفيذ أي إجراء متعلق بالمواعيد (الحجز أو إعادة الجدولة أو الإلغاء).
INSERT INTO appointment_db.translations (translation_id, phrase, language_code, translated_phrase, created_at, updated_at) VALUES (167, 'functions_calling_instructions', 'fr', 'Confirmez toujours avec le client avant d\'effectuer toute action liée à un rendez-vous (réservation, report ou annulation).
INSERT INTO appointment_db.translations (translation_id, phrase, language_code, translated_phrase, created_at, updated_at) VALUES (168, 'functions_calling_instructions', 'zh', '在执行任何与预约相关的操作（预订、重新安排或取消）之前，请务必与客户确认。
INSERT INTO appointment_db.translations (translation_id, phrase, language_code, translated_phrase, created_at, updated_at) VALUES (169, 'FINAL COMMANDS', 'en', 'FINAL COMMANDS', '2025-07-24 12:47:55', '2025-07-24 12:47:55');
